CREATE TABLE accounting_periods (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,fiscal_year SMALLINT UNSIGNED NOT NULL,period_no TINYINT UNSIGNED NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,status VARCHAR(10) NOT NULL DEFAULT 'open',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_accounting_period_year_no(fiscal_year,period_no),UNIQUE KEY uq_accounting_period_dates(start_date,end_date),KEY idx_accounting_period_status_dates(status,start_date,end_date),CONSTRAINT chk_accounting_period_no CHECK(period_no BETWEEN 1 AND 12),CONSTRAINT chk_accounting_period_dates CHECK(end_date>=start_date),CONSTRAINT chk_accounting_period_status CHECK(status IN('open','closed'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
